self.KB_CONTENT["card:781731"]={"id":"card:781731","ty":"card","sourceId":"781731","title":"『料件承認資料建立』中的『備註 (MH010)』為何？","ver":"GP4以上","topic":"備註","keywords":["備註","開窗","料件"],"y":"other","answer":"* 可使用[F2]片語資料查詢。* 也可開窗預設片語內容。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
