self.KB_CONTENT["card:777604"]={"id":"card:777604","ty":"card","sourceId":"777604","title":"『託外進貨單建立作業』中的『.驗收日期 (TI018)』為何？","ver":"GP4以上","topic":"進貨單","keywords":["進貨單","庫存","年月","大於"],"y":"other","answer":"* 輸入日期資料不可小於庫存現行年月，且須大於帳務凍結日期。* 輸入時預設驗收日期=託外進貨日期。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
