self.KB_CONTENT["card:782129"]={"id":"card:782129","ty":"card","sourceId":"782129","title":"『金融機構資料清單』的作業重點有哪些？","ver":"GP4以上","topic":"銀行","keywords":["銀行","符合","信用","印出"],"y":"explain","answer":"■作業重點1.至金融機構資料檔中擷取金融機構代號符合區間者，列印時按金融機構代號排序印出。2.金融機構種類：1.本國銀行、,2.外國銀行、3.信託投資、4.票券金融、5.信用合作社、6.產物保險、7.漁會信用、8.農會信用、9.郵局。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
