self.KB_CONTENT["field:824050"]={"id":"field:824050","ty":"field","sourceId":"824050","title":"單位材料成本","ver":"GP4.0.6.0 以上","topic":"","keywords":[],"job":"產品成本分析表","code":"","answer":"『產品成本分析表-CSTR05』的【單位材料成本】計算方式=材料成本 / (生產入庫 + 託外進貨 + 材料在製約量)","file":"fields.jsonl"};
