self.KB_CONTENT["field:884629"]={"id":"field:884629","ty":"field","sourceId":"884629","title":"發票字軌號碼","ver":"GP4.0.16.0以上","topic":"","keywords":[],"job":"進銷項資料檔審核錯誤清單","code":"","answer":"於營業稅電子申報繳稅系統－審核軟體 確認『營業人基本資料建檔』的【申報種類】，發現申報種類是「按月申報」，修改為「按期申報」，再重新開啟進銷項資料審核錯誤清單，已無 *符號出現在【資料所屬年月】及【發票字軌號碼】的資料","file":"fields.jsonl"};
