self.KB_CONTENT["field:758052"]={"id":"field:758052","ty":"field","sourceId":"758052","title":"選擇截止年月","ver":"iGP","topic":"","keywords":[],"job":"營業稅申報資料產生作業","code":"","answer":"* 此欄位不可空白。* 輸入的年月後續即成為營業稅申報資料的「截止年月」。","file":"fields.jsonl"};
